css_componentes.top_bar:
.top-bar { background-color: var(--sl-footer-bg); color: #94a3b8; font-size: 0.85rem; border-bottom: 1px solid #1e293b; }
.top-bar a { color: #cbd5e1; }
.top-bar a:hover { color: var(--gamer-primary); }

css_componentes.navbar:
header .navbar { background-color: var(--gamer-surface); border-bottom: 2px solid var(--gamer-border); padding: 15px 0; }
.navbar-brand-wrapper h1 { margin: 0; font-size: 2rem; color: var(--gamer-text); }
.navbar-nav .nav-link { font-family: var(--font-display); font-size: 1.1rem; color: var(--gamer-text); padding: 10px 15px !important; }
.navbar-nav .nav-link:hover { color: var(--gamer-primary); }

game_card.css:
.game-card {
  background-color: var(--gamer-surface);
  border: 1px solid var(--gamer-border);
  border-radius: 12px;
  overflow: hidden;
  transition: all 0.3s ease;
  height: 100%;
}
.game-card:hover {
  transform: translateY(-5px);
  border-color: var(--gamer-primary);
  box-shadow: 0 10px 25px rgba(var(--sl-primary),0.15);
}
.game-cover { position: relative; aspect-ratio: 16/9; overflow: hidden; background: #000; }
.game-cover img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s ease; opacity: 0.9; }
.game-card:hover .game-cover img { transform: scale(1.05); opacity: 1; }
.game-badge {
  position: absolute; top: 12px; left: 12px;
  background: linear-gradient(45deg, var(--gamer-primary), var(--gamer-secondary));
  color: #fff; font-family: var(--font-display); font-size: 0.8rem;
  padding: 4px 12px; border-radius: 20px; z-index: 2;
}

blockquote_vermelho_gamer.css:
.post-body-content blockquote {
  position: relative;
  background: linear-gradient(90deg, rgba(220,38,38,0.08) 0%, transparent 100%);
  border-left: 4px solid #dc2626;
  padding: 1.5rem 2rem;
  margin: 2rem 0;
  font-size: 1.2rem;
  font-style: italic;
  color: var(--gamer-text);
  border-radius: 0 8px 8px 0;
  box-shadow: inset 4px 0 10px -5px rgba(220,38,38,0.2);
  z-index: 1;
}
.post-body-content blockquote::before {
  content: '\201C';
  font-family: var(--font-display);
  font-size: 6rem;
  position: absolute;
  left: 10px;
  top: -20px;
  color: #dc2626;
  opacity: 0.15;
  line-height: 1;
  z-index: -1;
}
[data-bs-theme="dark"] .post-body-content blockquote {
  background: linear-gradient(90deg, rgba(239,68,68,0.15) 0%, transparent 100%);
}

label_tags_gamer.css:
.list-label-widget-content ul {
  list-style: none !important; padding: 0 !important; margin: 0 !important;
  display: flex; flex-wrap: wrap; gap: 10px;
}
.list-label-widget-content ul li { display: inline-flex; align-items: center; margin: 0; }
.list-label-widget-content ul li a, .post-bottom-tags a {
  display: inline-flex; align-items: center;
  background: var(--gamer-surface); color: var(--gamer-text);
  font-family: var(--font-display); font-size: 0.9rem; font-weight: 500;
  text-transform: uppercase; letter-spacing: 1px;
  padding: 8px 20px; border-radius: 4px;
  border: 1px solid var(--gamer-border);
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
  text-decoration: none !important;
  box-shadow: 0 4px 6px rgba(0,0,0,0.1);
}
.list-label-widget-content ul li a::before, .post-bottom-tags a::before {
  content: '\F325';
  font-family: 'bootstrap-icons';
  margin-right: 8px; font-size: 1rem;
  color: var(--gamer-primary);
  transition: color 0.3s ease;
}
.list-label-widget-content ul li a:hover, .post-bottom-tags a:hover {
  background: var(--gamer-primary); color: #ffffff !important;
  border-color: var(--gamer-primary);
  transform: translateY(-3px);
  box-shadow: 0 8px 20px rgba(var(--sl-primary),0.4);
}
.list-label-widget-content ul li a:hover::before, .post-bottom-tags a:hover::before { color: #ffffff; }
.list-label-widget-content ul li span[dir='ltr'] {
  background: var(--gamer-secondary);
  color: #ffffff; font-family: var(--font-display);
  font-size: 0.8rem; padding: 2px 8px;
  border-radius: 4px; margin-left: -12px;
  font-weight: 700; z-index: 2;
  border: 2px solid var(--gamer-bg);
  box-shadow: 0 2px 5px rgba(0,0,0,0.3);
}

popular_posts_thumbnail_css_only.css:
.popular-posts .item-thumbnail { flex-shrink: 0; margin-right: 15px; }
.popular-posts .item-thumbnail img {
  width: 100px; height: 56px;
  object-fit: cover; border-radius: 8px;
  display: block; transition: all 0.3s ease;
}
@media (min-width: 768px) {
  .popular-posts .item-thumbnail img { width: 150px; height: 85px; }
}

pagina_404_game_over.css:
.error-404-wrapper {
  min-height: 55vh; display: flex; flex-direction: column;
  justify-content: center; align-items: center; text-align: center;
  background-color: var(--gamer-surface);
  border: 2px solid var(--gamer-border);
  border-radius: 12px; margin: 3rem auto;
  padding: 4rem 2rem; max-width: 800px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.1);
  position: relative; overflow: hidden;
}
.error-404-wrapper::before {
  content: ''; position: absolute; top: -50%; left: -50%; width: 200%; height: 200%;
  background: radial-gradient(circle, rgba(var(--sl-primary),0.05) 0%, transparent 60%);
  pointer-events: none; z-index: 0;
}
.error-code {
  font-size: clamp(6rem, 15vw, 10rem);
  color: var(--gamer-primary);
  text-shadow: 5px 5px 0 rgba(6,182,212,0.4);
  line-height: 1; margin-bottom: 0;
  position: relative; z-index: 1;
}
.error-icon i {
  color: var(--gamer-secondary); font-size: 5rem;
  filter: drop-shadow(0 0 15px rgba(6,182,212,0.5));
  position: relative; z-index: 1;
}
.error-content { position: relative; z-index: 1; }
.btn-respawn {
  background: linear-gradient(45deg, var(--gamer-primary), var(--gamer-secondary));
  color: #fff !important; border: none;
  font-family: var(--font-display);
  letter-spacing: 1px; text-transform: uppercase;
  padding: 12px 35px; border-radius: 30px;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.btn-respawn:hover {
  transform: scale(1.05);
  box-shadow: 0 8px 25px rgba(var(--sl-primary),0.4);
}

footer.contact_form:
.contact-form-widget .form-control { background-color: rgba(255,255,255,0.05) !important; border: 1px solid rgba(255,255,255,0.1) !important; color: #ffffff !important; border-radius: 8px; }
.contact-form-widget .form-control:focus { border-color: var(--gamer-primary) !important; box-shadow: 0 0 0 0.25rem rgba(var(--sl-primary),0.25) !important; }
.contact-form-button-submit { background: linear-gradient(45deg, var(--gamer-primary), var(--gamer-secondary)); border: none !important; color: white !important; font-family: var(--font-display); font-size: 1.1rem; border-radius: 8px; padding: 10px 0; width: 100%; cursor: pointer; }

javascript.dark_mode_e_scroll:
document.addEventListener('DOMContentLoaded', () => {
  /* Dark Mode — default DARK para gaming sites */
  const setTheme = t => {
    document.documentElement.setAttribute('data-bs-theme', t);
    localStorage.setItem('theme', t);
    document.querySelector('.btn-dark-mode i').className = t === 'dark' ? 'bi bi-sun-fill fs-6 text-warning' : 'bi bi-moon-stars-fill fs-6';
  };
  setTheme(localStorage.getItem('theme') || 'dark');
  document.querySelectorAll('.btn-dark-mode').forEach(b =>
    b.addEventListener('click', () =>
      setTheme(document.documentElement.getAttribute('data-bs-theme') === 'dark' ? 'light' : 'dark')
    )
  );

  /* Scroll Animations */
  const obs = new IntersectionObserver(es =>
    es.forEach(e => { if (e.isIntersecting) { e.target.classList.add('visible'); obs.unobserve(e.target); } })
  , { threshold: 0.1 });
  document.querySelectorAll('.animate-up, .game-card').forEach((el, i) => {
    if (el.classList.contains('game-card')) el.style.transitionDelay = `${(i % 2) * 0.1}s`;
    el.classList.add('animate-up');
    obs.observe(el);
  });
});
